/**
 * Shared source-reading helpers for the structural tripwire suites.
 *
 * NOT named `*.test.ts` on purpose: `npm test` globs `test/*.test.ts`, so this
 * module is imported, never executed as a suite. It used to live inside
 * customer-actions-guards.test.ts and be imported from there, which made every
 * assertion in that file run a second time under the importing suite's name.
 */
export function stripComments(src: string): string {
  let out = "";
  let i = 0;
  const n = src.length;
  let quote: string | null = null;
  /** Last non-whitespace character emitted — decides `/` = regex vs. division. */
  let prev = "";

  /** Positions where a `/` begins a regex literal rather than a division. */
  const REGEX_PRECEDERS = new Set(["", "(", ",", "=", ":", "[", "!", "&", "|", "?", "{", "}", ";", "+", "-", "*", "%", "~", "^", "<", ">", "\n"]);
  const REGEX_KEYWORDS = /\b(return|typeof|case|in|of|delete|void|instanceof|new|do|else|yield|await)\s*$/;

  while (i < n) {
    const c = src[i];
    const next = src[i + 1];

    if (quote) {
      out += c;
      if (c === "\\") {
        // Escape: copy the escaped character too, so `\"` never closes a string.
        if (i + 1 < n) out += src[i + 1];
        i += 2;
        continue;
      }
      if (c === quote) quote = null;
      i++;
      continue;
    }

    if (c === '"' || c === "'" || c === "`") {
      quote = c;
      out += c;
      prev = c;
      i++;
      continue;
    }

    // `//` and `/*` are ALWAYS comments in valid JS — a regex literal cannot
    // begin with an unescaped `/` or a `*`. So comments win unconditionally, and
    // the regex branch below only ever sees a genuine literal.
    if (c === "/" && next === "/") {
      while (i < n && src[i] !== "\n") i++;
      out += " ";
      continue;
    }
    if (c === "/" && next === "*") {
      i += 2;
      while (i < n && !(src[i] === "*" && src[i + 1] === "/")) i++;
      i += 2;
      out += " ";
      continue;
    }

    // A regex literal must be consumed whole, or its escaped slashes (`\/\/` in
    // `/^https?:\/\//`) look like the start of a comment and eat the rest of the
    // line — silently deleting real code from everything asserted below.
    if (c === "/" && (REGEX_PRECEDERS.has(prev) || REGEX_KEYWORDS.test(out))) {
      out += c;
      i++;
      let inClass = false;
      for (; i < n; i++) {
        const r = src[i];
        out += r;
        if (r === "\\") {
          if (i + 1 < n) out += src[i + 1];
          i++;
          continue;
        }
        if (r === "[") inClass = true;
        else if (r === "]") inClass = false;
        else if (r === "/" && !inClass) {
          i++;
          break;
        } else if (r === "\n") {
          // Not a regex after all (unterminated) — stop rather than run away.
          i++;
          break;
        }
      }
      prev = "/";
      continue;
    }

    out += c;
    if (!/\s/.test(c) || c === "\n") prev = c;
    i++;
  }
  return out;
}
