1	import { NextResponse } from "next/server";
2	import { checkRateLimit } from "@/lib/rate-limit";
3	
4	/**
5	 * Small shared helpers for the public /api/tools/* network endpoints:
6	 * client-IP extraction, per-IP rate limiting, and consistent JSON errors.
7	 */
8	
9	/** First hop of x-forwarded-for is the real client (nginx appends downstream). */
10	export function clientIp(req: Request): string {
11	  const xff = req.headers.get("x-forwarded-for") ?? "";
12	  const first = xff.split(",")[0]?.trim();
13	  return first || req.headers.get("x-real-ip") || "unknown";
14	}
15	
16	/** JSON error with a status code. */
17	export function jsonError(message: string, status = 400) {
18	  return NextResponse.json({ ok: false, error: message }, { status });
19	}
20	
21	/**
22	 * Per-IP throttle for a named tool. Returns a 429 response when over the limit,
23	 * otherwise null (caller proceeds). Defaults: 20 requests / minute / IP / tool.
24	 */
25	export function toolRateLimit(
26	  req: Request,
27	  tool: string,
28	  opts: { max?: number; windowMs?: number } = {},
29	): NextResponse | null {
30	  const { max = 20, windowMs = 60_000 } = opts;
31	  const rl = checkRateLimit(`tool:${tool}:${clientIp(req)}`, { max, windowMs });
32	  if (!rl.ok) {
33	    return NextResponse.json(
34	      { ok: false, error: `Rate limit reached. Try again in ${rl.retryAfterSec}s.` },
35	      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } },
36	    );
37	  }
38	  return null;
39	}
40	
41	/** Read and cap a single string field from a JSON body. */
42	export async function readField(req: Request, field: string, maxLen = 253): Promise<string> {
43	  const body = (await req.json().catch(() => ({}))) as Record<string, unknown>;
44	  const v = body[field];
45	  return typeof v === "string" ? v.trim().slice(0, maxLen) : "";
46	}
