89	/**
90	 * Is a top-up promo code redeemable AT ALL right now?
91	 *
92	 * This mirrors, deliberately, the two guards at the top of `topUp`
93	 * (lib/actions.ts): the demo gateway is the ONLY code path in the product that
94	 * reads the `nxeon_coupon` cookie and grants the bonus, and it refuses when
95	 * NODE_ENV is production or when Stripe is configured. The real card path
96	 * (app/api/stripe/checkout/route.ts -> `creditCheckoutSession`) credits
97	 * `session.amount_total` verbatim, so it cannot add a bonus on top of what was
98	 * charged — no amount of work in this file changes that.
99	 *
100	 * So when this returns false a promo code cannot be honoured by anything, and
101	 * accepting one would reproduce the exact defect this codebase keeps shipping: a
102	 * green "Code applied" that is read by nothing (compare the auto-suspend kill
103	 * switch, and the domain markup that displayed 0% while charging 25%).
104	 *
105	 * TO TURN COUPONS BACK ON, one change is needed in a file this change does not
106	 * own — `lib/fulfil-checkout.ts`, in its `kind: "topup"` branch:
107	 *
108	 *   1. `app/api/stripe/checkout/route.ts` re-validates the cookie's code against
109	 *      the REAL amount and stamps `nxeonCoupon: JSON.stringify({ couponId,
110	 *      bonusCents })` into the session metadata. Computing the bonus once, at
111	 *      session creation, against the amount the customer is actually charged is
112	 *      what makes "never charge more than displayed" hold — the $25 preview
113	 *      amount must never be what gets paid out.
114	 *   2. `fulfilCheckoutSession` calls `claim(sessionId, "topup")` — which it does
115	 *      not do today, because a plain top-up needs no fulfilment — and grants the
116	 *      bonus only if it wins the claim.
117	 *   3. The grant is one `$transaction`: increment `balanceCents`, insert the
118	 *      `WalletTransaction`, insert the `CouponRedemption`, increment
119	 *      `Coupon.timesRedeemed`.
120	 *
121	 * That gives THREE independent stops against a replayed webhook paying twice: the
122	 * UNIQUE `FulfilledSession.stripeSessionId` claim, the
123	 * `@@unique([couponId, userId])` on `CouponRedemption`, and metadata that fixes
124	 * the bonus to one session. Any one of them alone is sufficient; the redemption
125	 * constraint is the one that also survives a session being replaced.
126	 *
127	 * Once the bonus is granted there, replace the body of this function with
128	 * `return true`.
129	 */
130	async function topupCouponRedeemable(): Promise<boolean> {
131	  const { stripeConfigured } = await import("./stripe");
132	  return process.env.NODE_ENV !== "production" && !stripeConfigured();
133	}
