135	/**
136	 * Validate a promo code for the CURRENT user against a top-up of `baseCents` and
137	 * return the bonus that would be credited. Read-only: it never mutates state,
138	 * so it is safe to call both for the live preview (CouponField) and again inside
139	 * `topUp` to compute the real bonus. Enforces redeemability / active / expiry /
140	 * scope / kind / minAmount / maxRedemptions / firstTimeOnly / one-per-user rules.
141	 *
142	 * Every `ok: false` here carries a reason the customer can read. That matters
143	 * because a caller may use `ok: true` as a promise: `CouponField` renders a green
144	 * "Code applied" from it, so this function must never say yes to something the
145	 * money path will not honour.
146	 */
147	export async function applyCouponToTopup(
148	  code: string,
149	  baseCents: number
150	): Promise<CouponApplyResult> {
151	  const user = await requireUser();
152	  // Global kill-switch: when coupons are disabled no code may be redeemed.
153	  // Checked here so both the live preview and the real `topUp` apply are covered.
154	  if (!(await getSettingBool("coupons_enabled", true))) {
155	    return { ok: false, error: "Promo codes are currently disabled." };
156	  }
157	  // Honesty gate. Refuse BEFORE looking the code up, so we neither promise a
158	  // bonus no code path can grant nor leak which codes exist. See
159	  // `topupCouponRedeemable` for the single change that lifts this.
160	  if (!(await topupCouponRedeemable())) {
161	    return {
162	      ok: false,
163	      error:
164	        "Promo codes can’t be applied to card payments yet, so this code has not been applied — nothing has been charged. Contact support if you were given this code.",
165	    };
166	  }
167	  const normalized = String(code ?? "").trim().toUpperCase();
168	  if (!normalized) return { ok: false, error: "Enter a promo code." };
169	
170	  const coupon = await db.coupon.findUnique({ where: { code: normalized } });
171	  if (!coupon || !coupon.active) return { ok: false, error: "That code isn’t valid." };
172	  if (coupon.scope === "ORDER") {
173	    return { ok: false, error: "This code only applies to server orders." };
174	  }
175	  // "Fixed cents off" is a DISCOUNT, and a wallet top-up has nothing to discount:
176	  // the customer names the amount and pays exactly that. This kind used to be
177	  // handed to `couponBonusForTopup` and paid out as a bonus, so a coupon that
178	  // /admin/coupons renders as "$5.00 off" credited the customer $5.00 of free
179	  // balance instead (QA-PRELAUNCH P1-7). Refuse it rather than silently
180	  // reinterpret an admin's intent as its opposite.
181	  if (coupon.kind === "FIXED_CENTS") {
182	    return {
183	      ok: false,
184	      error: "This code is money off an order, not top-up credit — it can’t be used here.",
185	    };
186	  }
187	  if (coupon.expiresAt && coupon.expiresAt.getTime() < Date.now()) {
188	    return { ok: false, error: "This code has expired." };
189	  }
190	  if (coupon.maxRedemptions !== null && coupon.timesRedeemed >= coupon.maxRedemptions) {
191	    return { ok: false, error: "This code has reached its redemption limit." };
192	  }
193	  if (coupon.minAmountCents !== null && baseCents < coupon.minAmountCents) {
194	    return {
195	      ok: false,
196	      error: `Add at least $${(coupon.minAmountCents / 100).toFixed(2)} to use this code.`,
197	    };
198	  }
199	
200	  // One redemption per user (mirrors the @@unique([couponId,userId]) constraint).
201	  const already = await db.couponRedemption.findUnique({
202	    where: { couponId_userId: { couponId: coupon.id, userId: user.id } },
203	  });
204	  if (already) return { ok: false, error: "You’ve already used this code." };
205	
206	  if (coupon.firstTimeOnly) {
207	    // "First-time" = the user has never received a positive wallet credit before.
208	    const priorCredits = await db.walletTransaction.count({
209	      where: { userId: user.id, amountCents: { gt: 0 } },
210	    });
211	    if (priorCredits > 0) {
212	      return { ok: false, error: "This code is for first-time customers only." };
213	    }
214	  }
215	
216	  const bonusCents = Math.max(0, couponBonusForTopup(coupon, baseCents));
217	  return {
218	    ok: true,
219	    couponId: coupon.id,
220	    code: coupon.code,
221	    bonusCents,
222	    label: describeCoupon(coupon),
223	  };
224	}
