245	export async function adminCreateCoupon(
246	  prev: any,
247	  formData: FormData
248	): Promise<{ error?: string; ok?: boolean }> {
249	  const admin = await requireAdmin();
250	  const rawExpires = String(formData.get("expiresAt") ?? "").trim();
251	  const rawMin = String(formData.get("minAmountCents") ?? "").trim();
252	  const rawMax = String(formData.get("maxRedemptions") ?? "").trim();
253	  const parsed = couponSchema.safeParse({
254	    code: formData.get("code"),
255	    kind: formData.get("kind"),
256	    scope: formData.get("scope"),
257	    value: formData.get("value"),
258	    firstTimeOnly: formData.get("firstTimeOnly") === "on",
259	    minAmountCents: rawMin === "" ? undefined : rawMin,
260	    maxRedemptions: rawMax === "" ? undefined : rawMax,
261	    expiresAt: rawExpires === "" ? undefined : rawExpires,
262	    note: formData.get("note") || undefined,
263	  });
264	  if (!parsed.success) {
265	    return { error: parsed.error.issues[0]?.message ?? "Invalid coupon." };
266	  }
267	  const data = parsed.data;
268	  if (data.kind === "PERCENT" && data.value > 100) {
269	    return { error: "Percent value must be between 1 and 100." };
270	  }
271	  const code = data.code.toUpperCase();
272	
273	  const existing = await db.coupon.findUnique({ where: { code } });
274	  if (existing) return { error: "A coupon with that code already exists." };
275	
276	  let expiresAt: Date | null = null;
277	  if (data.expiresAt) {
278	    const d = new Date(data.expiresAt);
279	    if (Number.isNaN(d.getTime())) return { error: "Invalid expiry date." };
280	    expiresAt = d;
281	  }
282	
283	  await db.coupon.create({
284	    data: {
285	      code,
286	      kind: data.kind,
287	      scope: data.scope,
288	      value: data.value,
289	      firstTimeOnly: data.firstTimeOnly,
290	      minAmountCents: data.minAmountCents ?? null,
291	      maxRedemptions: data.maxRedemptions ?? null,
292	      expiresAt,
293	      note: data.note ?? null,
294	    },
295	  });
296	  await db.auditLog.create({
297	    data: { userId: admin.id, action: "admin.coupon_create", detail: code },
298	  });
299	  revalidatePath("/admin/coupons");
300	  return { ok: true };
301	}
