331	/**
332	 * If `userId` was referred and hasn't been rewarded yet, credit BOTH the referred
333	 * user and their referrer with REFERRAL_REWARD_CENTS, exactly once. Guarded by an
334	 * atomic claim on `referralRewardedAt` so concurrent paid actions can't double-pay.
335	 * Callable from `topUp` in lib/actions.ts and from `placeOrder` in lib/order.ts
336	 * after a paid action.
337	 */
338	export async function maybeRewardReferral(userId: string): Promise<boolean> {
339	  await assertInternalGrowthCaller(userId);
340	  // Feature flag: the referral program can be switched off platform-wide.
341	  if (!(await getSettingBool("feature_referrals", true))) return false;
342	
343	  // Settings → Growth writes `referral_reward_cents` and displays it, but NOTHING
344	  // read it — the payout used the env-backed `referralRewardCents()` instead, so an
345	  // operator changing the reward saw "Saved." and the platform kept paying the old
346	  // amount. Same shape as the domain markup showing 0% while charging 25%, and the
347	  // auto-suspend switch that silenced nothing.
348	  //
349	  // Clamped, and the ceiling matters more here than anywhere else: this reward is
350	  // paid to BOTH the referrer and the referred user, so a stray digit costs twice
351	  // per signup and scales with signup volume. 100_000 cents = $1,000 a side is
352	  // already absurd; anything beyond it is certainly a typo.
353	  const reward = Math.min(
354	    Math.max(await getSettingInt("referral_reward_cents", referralRewardCents()), 0),
355	    100_000
356	  );
357	  if (reward <= 0) return false;
358	
359	  const user = await db.user.findUnique({ where: { id: userId } });
360	  if (!user || !user.referredById || user.referralRewardedAt) return false;
361	  const referrerId = user.referredById;
362	
363	  // Atomically claim the reward; if another concurrent action already did, bail.
364	  const claim = await db.user.updateMany({
365	    where: { id: userId, referralRewardedAt: null, referredById: { not: null } },
366	    data: { referralRewardedAt: new Date() },
367	  });
368	  if (claim.count === 0) return false;
369	
370	  await db.$transaction([
371	    db.user.update({ where: { id: userId }, data: { balanceCents: { increment: reward } } }),
372	    db.walletTransaction.create({
373	      data: { userId, amountCents: reward, description: "Referral bonus — welcome reward" },
374	    }),
375	    db.user.update({ where: { id: referrerId }, data: { balanceCents: { increment: reward } } }),
376	    db.walletTransaction.create({
377	      data: {
378	        userId: referrerId,
379	        amountCents: reward,
380	        description: "Referral bonus — you referred a friend",
381	      },
382	    }),
383	  ]);
384	
385	  // Best-effort in-app notifications, filtered through the notification policy.
386	  //
387	  // `referral_bonus` is ACCOUNT tier, so the in-app bell is never suppressed —
388	  // these rows are the customer's record of money that entered their wallet, and
389	  // hiding a credit would be the same "it silently disappeared" failure the
390	  // preferences exist to cure. The gate is here anyway so the tier in
391	  // `lib/prefs.ts` stays the single decider: if this kind is ever reclassified,
392	  // the filter starts biting without anyone having to remember this call site.
393	  try {
394	    const rows = [
395	      {
396	        userId,
397	        title: `You earned a $${(reward / 100).toFixed(2)} referral bonus`,
398	        href: "/dashboard/billing",
399	      },
400	      {
401	        userId: referrerId,
402	        title: `A friend you referred just joined — $${(reward / 100).toFixed(2)} added`,
403	        href: "/dashboard/refer",
404	      },
405	    ];
406	    const allowed: typeof rows = [];
407	    for (const row of rows) {
408	      if (await mayDeliverTo(row.userId, "referral_bonus", "inapp")) allowed.push(row);
409	    }
410	    if (allowed.length > 0) await db.notification.createMany({ data: allowed });
411	  } catch {
412	    /* best-effort */
413	  }
414	  return true;
415	}
