import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { stripComments } from "./_source-tools.ts";

/**
 * Structural guards over the CUSTOMER-FACING SERVER ACTIONS.
 *
 * These are the functions the portal calls to act on a customer's behalf, and
 * they are the widest attack surface in the product for one reason that is easy
 * to forget while reading them: **every export of a `"use server"` file is a
 * public network endpoint**. Not "callable from the page that imports it" —
 * callable by a stranger with curl. That property is what turned
 * `verifyTotpForUser` into an unauthenticated 2FA brute-force oracle
 * (QA-PRELAUNCH P0-2) and is why `lib/safe-next.ts` and `lib/totp-verify.ts`
 * exist as plain modules.
 *
 * A reviewer can hold that in their head for one file. Nobody holds it for
 * fifteen, forever, while adding a sixteenth. So it is asserted here instead.
 *
 * ── WHY THE SOURCE IS STRIPPED OF COMMENTS FIRST ─────────────────────────────
 * This codebase documents its incidents in the code, at length. A tripwire that
 * greps raw source for `assertNotImpersonating` matches the comment explaining
 * why the guard matters — so it passes on a function whose guard was deleted and
 * whose comment survived, which is the exact edit a careless refactor makes.
 * `stripComments` removes comments (and only comments) before anything is
 * matched, so every assertion below is about executable code.
 */

const LIB = join(import.meta.dirname, "..", "lib");

/* ------------------------------------------------------------------ *
 * Source utilities
 * ------------------------------------------------------------------ */

/**
 * Remove `//` and slash-star comments while preserving string and template
 * literals verbatim (a `"https://…"` is not a comment, and neither is the `//`
 * inside `/^https?:\/\//`). Replaces each comment with a single space so token
 * boundaries survive.
 */


function source(file: string): string {
  return stripComments(readFileSync(join(LIB, file), "utf8"));
}

/** Every `export async function NAME` in a (comment-stripped) module. */
function exportedActions(src: string): string[] {
  return [...src.matchAll(/export\s+async\s+function\s+([A-Za-z0-9_$]+)\s*\(/g)].map((m) => m[1]);
}

/**
 * The body of `export async function NAME`, by brace matching from its opening
 * `{`. Braces inside strings are ignored — every string literal in these files
 * is balanced anyway, but template literals interpolate `${…}` and must not be
 * allowed to unbalance the count.
 */
function bodyOf(src: string, name: string): string {
  const decl = new RegExp(`export\\s+async\\s+function\\s+${name}\\s*\\(`).exec(src);
  assert.ok(decl, `expected to find an exported action named ${name}`);

  // Walk the parameter list to its closing paren, then find the body's opening
  // brace. The brace cannot simply be "the next `{`": a return annotation like
  // `Promise<{ error?: string }>` puts one in the way, and matching from there
  // returns the TYPE instead of the body — which silently makes every assertion
  // about that function vacuous. So skip braces that sit inside `<…>`.
  let i = src.indexOf("(", decl.index);
  let parens = 0;
  let quote: string | null = null;
  for (; i < src.length; i++) {
    const c = src[i];
    if (quote) {
      if (c === "\\") i++;
      else if (c === quote) quote = null;
      continue;
    }
    if (c === '"' || c === "'" || c === "`") quote = c;
    else if (c === "(") parens++;
    else if (c === ")" && --parens === 0) break;
  }
  assert.ok(i < src.length, `unbalanced parameter list for ${name}`);

  let angles = 0;
  for (i++; i < src.length; i++) {
    const c = src[i];
    if (c === "<") angles++;
    else if (c === ">") angles = Math.max(0, angles - 1);
    else if (c === "{" && angles === 0) break;
  }
  assert.ok(i < src.length, `no body found for ${name}`);
  const start = i;
  let depth = 0;
  quote = null;
  for (; i < src.length; i++) {
    const c = src[i];
    if (quote) {
      if (c === "\\") {
        i++;
        continue;
      }
      if (c === quote) quote = null;
      continue;
    }
    if (c === '"' || c === "'" || c === "`") {
      quote = c;
      continue;
    }
    if (c === "{") depth++;
    else if (c === "}") {
      depth--;
      if (depth === 0) return src.slice(start, i + 1);
    }
  }
  assert.fail(`unbalanced body for ${name}`);
}

