] as const;

/**
 * Calls that establish WHO is asking. `owned*` are this codebase's per-resource
 * helpers, each of which starts with `requireUser()` and then proves ownership.
 */
const AUTH_MARKERS = [
  "requireUser(",
  "requireAdmin(",
  "requireArea(",
  "requireStaff(",
  "realUser(",
  "ownedServer(",
  "ownedVolume(",
  "ownedDomain(",
  "ownedCertificate(",
  "ownedTargetServer(",
  "assertInternalGrowthCaller(",
];

/**
 * The only endpoints that are SUPPOSED to answer an anonymous caller: the
 * sign-up / sign-in / sign-out trio. Each rate-limits itself; see lib/actions.ts.
 */
const INTENTIONALLY_PUBLIC = new Set(["register", "login", "logout"]);

test("every exported server action identifies its caller inside the function", () => {
  const unguarded: string[] = [];
  for (const file of ACTION_FILES) {
    const src = source(file);
    assert.ok(src.includes('"use server"'), `${file} should declare "use server"`);
    for (const name of exportedActions(src)) {
      if (INTENTIONALLY_PUBLIC.has(name)) continue;
      const body = bodyOf(src, name);
      if (!AUTH_MARKERS.some((m) => body.includes(m))) unguarded.push(`${file}:${name}`);
    }
  }
  assert.deepEqual(
    unguarded,
    [],
    "these exports are network-reachable by an anonymous caller with no identity check",
  );
});

