 * ------------------------------------------------------------------ */

/**
 * Calls that move a customer's money: a wallet debit, a wallet credit, a Stripe
 * Checkout opened in their name, or one of the helpers that wraps those.
 */
const MONEY_MARKERS = [
  "debitWallet(",
  "balanceCents: { increment",
  "createOrderCheckout(",
  "createResizeCheckout(",
  "createDiskExpandCheckout(",
  "placeOrder(",
  "applyResize(",
  "applyDiskExpand(",
  "settleFailedTransferIn(",
];

/**
 * Actions that move money WITHOUT the impersonation guard, by design — because
 * they are staff tools whose whole purpose is acting on someone else's balance,
 * or an internal reward path with its own caller check.
 *
 * The allowlist is self-policing: each entry must independently prove it is
 * staff-gated or internal, asserted below. An action cannot be quietly parked
 * here to dodge the guard.
 */
const STAFF_OR_INTERNAL_MONEY = new Map<string, string[]>([
  ["actions.ts:adminCreditUser", ["requireAdmin("]],
  ["actions-affiliate.ts:adminUpdatePayout", ["requireArea("]],
  ["actions-growth.ts:maybeRewardReferral", ["assertInternalGrowthCaller("]],
]);

function moneyActions(): { key: string; body: string }[] {
  const found: { key: string; body: string }[] = [];
  for (const file of ACTION_FILES) {
    const src = source(file);
    for (const name of exportedActions(src)) {
      const body = bodyOf(src, name);
      if (MONEY_MARKERS.some((m) => body.includes(m))) found.push({ key: `${file}:${name}`, body });
    }
  }
  return found;
}

test("every customer-facing action that moves money calls assertNotImpersonating", () => {
  const missing: string[] = [];
  for (const { key, body } of moneyActions()) {
    if (STAFF_OR_INTERNAL_MONEY.has(key)) continue;
    if (!body.includes("assertNotImpersonating(")) missing.push(key);
  }
  assert.deepEqual(
    missing,
    [],
    "an admin impersonating a customer could spend or move that customer's money here",
  );
});

test("the impersonation guard runs BEFORE the first money movement", () => {
  const late: string[] = [];
  for (const { key, body } of moneyActions()) {
    if (STAFF_OR_INTERNAL_MONEY.has(key)) continue;
    const guardAt = body.indexOf("assertNotImpersonating(");
    const moneyAt = Math.min(
      ...MONEY_MARKERS.map((m) => body.indexOf(m)).filter((n) => n >= 0),
    );
    if (guardAt < 0 || guardAt > moneyAt) late.push(key);
  }
  assert.deepEqual(late, [], "the guard must be reached before anything is charged or credited");
});

test("every money action exempted from the guard is genuinely staff-gated or internal", () => {
  const bodies = new Map(moneyActions().map((a) => [a.key, a.body]));
  for (const [key, required] of STAFF_OR_INTERNAL_MONEY) {
    const body = bodies.get(key);
    assert.ok(body, `${key} is allowlisted but no longer moves money — remove it from the list`);
    assert.ok(
      required.some((m) => body!.includes(m)),
      `${key} is exempt from assertNotImpersonating and must prove it is staff-gated (${required.join(", ")})`,
    );
  }
});

