 * Subscribe one of the caller's registered domains to an email plan. Validates
 * domain ownership + plan availability, then atomically debits the wallet and
 * creates the EmailSubscription with an expiry set from the plan term.
 *
 * The subscription is created ACTIVE (billing-wise), but no mailboxes are
 * provisioned with a mail provider yet — that integration is pending, and the
 * UI surfaces every mailbox as "provisioning" until it lands.
 */
export async function orderEmailHosting(
  domainName: string,
  emailPlanId: string,
): Promise<Result> {
  const user = await requireUser();
  // Purchase gate: an unverified address means we cannot reach the person we
  // are about to charge. See lib/email-verification.ts.
  const unverified = await emailVerificationError(user);
  if (unverified) return { error: unverified };

  const name = String(domainName ?? "")
    .trim()
    .toLowerCase()
    .replace(/\.$/, "");
  if (!name) return { error: "Enter a domain." };
  if (!domainRe.test(name)) return { error: "Enter a valid domain (e.g. example.com)." };

  // Is the domain registered inside Nxeon? If so we control its DNS and can
  // treat mail as pre-verifiable; otherwise it's an EXTERNAL domain that must be
  // verified via DNS before mail flows.
  const inAccount = await db.domain.findFirst({ where: { name, userId: user.id } });
  const external = !inAccount;

  const plan = await db.emailPlan.findUnique({ where: { id: emailPlanId } });
  if (!plan || !plan.active) return { error: "That email plan isn't available." };

  // One subscription per domain — ACROSS ALL ACCOUNTS, not just this one.
  //
  // SECURITY (fixed 2026-07-25): this lookup was scoped to `userId: user.id`,
  // which let anyone buy a subscription for a domain another customer already
  // held. That was a cross-tenant email takeover: `addMailbox` only checks that
  // the SUBSCRIPTION belongs to the caller, and Mailcow keys mailboxes by
  // ADDRESS — so an attacker could create admin@victim.com under their own
  // subscription, call resetMailboxPassword() (which passes its ownership check
  // because the row is theirs), and have the password of the victim's real, live
  // mailbox handed back to them. Cost of the attack: the cheapest email plan.
  const dupe = await db.emailSubscription.findFirst({
    where: { domainName: name, status: { not: "CANCELLED" } },
  });
  if (dupe) {
    return {
      error:
        dupe.userId === user.id
          ? "This domain already has an email subscription."
          : "That domain is already set up for email on Nxeon. If it belongs to you, contact support and we'll verify ownership and move it across.",
    };
  }

  // Seasonal promo = HONEST intro discount on the FIRST term only. The renewal
  // path (worker/product-renewals.ts) bills plan.priceCents unchanged, so the
  // strikethrough shown on the pricing page is the real renewal price and this
  // discounted value is the real first-term price — displayed === charged.
  const promo = currentPromo(new Date());
  const chargeCents = promoPriceCents(plan.priceCents, promo);
  const promoNote = promo.discountPercent > 0 ? ` — ${promo.name} ${promo.discountPercent}% off first term` : "";
  if (user.balanceCents < chargeCents) {
    return { error: "Insufficient balance. Top up your wallet first." };
  }

  try {
    await db.$transaction(async (tx) => {
      await debitWallet(tx, user.id, chargeCents);
      await tx.walletTransaction.create({
        data: {
          userId: user.id,
          amountCents: -chargeCents,
          description: `Business Email: ${plan.name} for ${name}${promoNote}`,
        },
      });
      await tx.emailSubscription.create({
        data: {
          userId: user.id,
          domainName: name,
          emailPlanId: plan.id,
          status: "ACTIVE",
          autoRenew: true,
          expiresAt: addMonths(new Date(), plan.termMonths),
          // In-account domains: we control DNS, so treat as verified now. External
          // domains: not verified until the customer publishes DNS + we confirm it.
          external,
          verified: !external,
          verifiedAt: external ? null : new Date(),
          verifyToken: external ? randomBytes(24).toString("hex") : null,
        },
      });
    });
  } catch (e) {
    if (e instanceof InsufficientBalanceError) {
      return { error: "Insufficient balance. Top up your wallet first." };
    }
    throw e;
  }

  } catch (e) {
    notes.push("RCON push skipped (unavailable). A restart is required for changes to take effect.");
    console.error("[game-config] minecraft rcon error", e);
  }

  return {
    ok: true,
    applied: [`Wrote ${Object.keys(updates).length} setting(s) to ${path}.`],
    notes: notes.length ? notes : ["Restart the server for deploy-time settings (hardcore, online-mode) to take effect."],
  };
}

/**
 * Best-effort Minecraft RCON push. Reads rcon config from the (updated)
 * server.properties; if RCON is enabled, a password is set, and `mcrcon` exists
 * on the box, pushes the live-editable settings. Anything missing → note a restart.
 */
async function tryMinecraftRcon(conn: Client, props: string, v: Values, notes: string[]): Promise<void> {
  const kv = parseKeyValue(props);
  const enabled = kv["enable-rcon"] === "true";
  const password = kv["rcon.password"] ?? "";
  const port = kv["rcon.port"] || "25575";
  if (!enabled || !password) {
    notes.push("RCON is not enabled — restart the server to apply the new settings live.");
    return;
  }
  const which = await execRemote(conn, "command -v mcrcon || true");
  if (!which.stdout.trim()) {
    notes.push("RCON is enabled but `mcrcon` is not installed — restart to apply live.");
    return;
  }

  // A conservative set of safe live commands. TODO(rcon): expand once the exact
  // runtime command set is verified for the target Minecraft build.
  const cmds: string[] = [];
  if (v["difficulty"] != null) cmds.push(`difficulty ${String(v["difficulty"])}`);
  if (v["white-list"] != null) cmds.push(`whitelist ${bool(v["white-list"]) === "true" ? "on" : "off"}`);
  if (v["pvp"] != null || v["max-players"] != null || v["motd"] != null) cmds.push("reload");
  if (cmds.length === 0) return;

  const quoted = cmds.map((c) => `'${shq(c)}'`).join(" ");
  const res = await execRemote(
    conn,
    `mcrcon -H 127.0.0.1 -P ${shq(port)} -p '${shq(password)}' ${quoted} 2>&1 || true`
  );
  notes.push(res.code === 0 ? "Pushed live settings via RCON." : "RCON push attempted (some settings may need a restart).");
}

// ---------------------------------------------------------------------------
// Rust → server.cfg (server.<convar> value)
// ---------------------------------------------------------------------------

async function applyRust(conn: Client, sftp: SFTPWrapper, v: Values): Promise<ApplyOutcome> {
  // Rust reads server.cfg from <identity>/cfg/server.cfg — the identity dir is
  // deployment-specific, so we locate it rather than guessing.
  // TODO(paths): confirm the server identity/install path for the Rust image.
  const path = await remoteLocate(
    conn,
    ["/opt/rust/server/rustserver/cfg/server.cfg", "/opt/rust/server/cfg/server.cfg", "/home/rust/server/rustserver/cfg/server.cfg"],
    ["/opt/rust", "/home/rust", "/home/steam", "/opt"],
    "server.cfg"
  );
  if (!path) {
    return { ok: false, applied: [], notes: ["Could not locate Rust server.cfg — nothing was changed."] };
  }
  const existing = await sftpRead(sftp, path);
  if (existing == null) {
    return { ok: false, applied: [], notes: [`server.cfg disappeared at ${path} — nothing was changed.`] };
  }

  // Field keys map to `server.<key>` convars; strings are quoted.
  const updates: Record<string, string> = {};
  for (const [key, val] of Object.entries(v)) {
    const convar = `server.${key}`;
    if (typeof val === "boolean") updates[convar] = bool(val);
    else if (typeof val === "number") updates[convar] = String(val);
    else updates[convar] = `"${String(val).replace(/"/g, '\\"')}"`;
  }
  const next = updateConvars(existing, updates);
  await sftpWrite(sftp, path, next);

  // Rust RCON is a WebSocket (rcon.web) protocol — not attempted here.
  // TODO(rcon): push live convars (hostname/maxplayers/pve) via the Rust
  // WebSocket RCON if the server exposes it. For now note a restart/wipe.
  return {
    ok: true,
    applied: [`Wrote ${Object.keys(updates).length} convar(s) to ${path}.`],
    notes: ["Restart the server to apply. World-size/seed changes only take effect on the next map wipe."],
  };
}

