/* -------------------------------------------------------------------------- */
/*                   EmailLog: what may be kept, and for how long              */
/* -------------------------------------------------------------------------- */

/**
 * Query parameters whose VALUE is a bearer secret — possession of the string is
 * the whole authentication.
 *
 * WHY THIS EXISTS. Two flows put a live credential inside an email body:
 *
 *   lib/actions-account.ts     `${APP_URL}/reset-password?token=${token}`
 *   lib/email-verification.ts  `${base}/api/auth/verify-email?token=${token}`
 *
 * In both, `token` is the RAW `randomBytes(32).toString("base64url")` and only
 * its SHA-256 ever reaches the database — `PasswordResetToken.tokenHash` /
 * `EmailVerificationToken.tokenHash`. That hashing is the entire reason those
 * columns are shaped the way they are, and `EmailVerificationToken`'s own schema
 * comment states the guarantee it buys: "a database leak hands out no working
 * links."
 *
 * `recordEmail` then wrote the rendered body — raw link and all — straight into
 * `EmailLog.html`, on EVERY path (`lib/mailer.ts` logs success, SMTP failure and
 * not-configured alike). One SELECT on `EmailLog` handed out working password
 * reset links for every account that had asked for one, which cancelled the
 * hashing outright: the token table was hardened and the audit log was not.
 * Same for a database backup, where nothing expires and no pruning ran.
 *
 * The redaction happens HERE, at the single choke point every message passes
 * through, rather than per template — a per-template rule is one someone can
 * forget the next time a token-bearing email is added, and nothing would fail.
 *
 * The admin preview keeps everything it exists for: layout, copy, styling,
 * deliverability. An operator debugging "did the reset mail render correctly"
 * needs to see that the link is present and well-formed, not to be able to walk
 * through it into a customer's account.
 */
const SECRET_QUERY_PARAM =
  /((?:\?|&amp;|&)(?:token|code|key|secret|otp|invite|auth|sig|signature|password|pw)=)[^&"'<>\s#]+/gi;

/** What a redacted value is replaced with. Visible, so nobody thinks it was empty. */
export const REDACTED = "[redacted]";

/**
 * Strip bearer secrets out of an email body before it is persisted.
 *
 * Applied to the STORED copy only — `lib/mailer.ts` hands the real HTML to the
 * SMTP transport first, so the message the customer receives is untouched and
 * their link still works.
 */
export function redactEmailSecrets(html: string): string {
  return String(html ?? "").replace(SECRET_QUERY_PARAM, `$1${REDACTED}`);
}

/**
 * How long an `EmailLog` row is kept. There was no retention at all: every
 * message ever sent was kept forever, which is what turned a rendering-preview
 * convenience into an indefinite archive of customer correspondence. 90 days is
 * long enough to debug a deliverability complaint and short enough that the log
 * is not a second copy of the customer database.
 */
export function emailLogRetentionDays(): number {
  const raw = Number(process.env.NXEON_EMAIL_LOG_RETENTION_DAYS ?? 90);
  if (!Number.isFinite(raw) || raw <= 0) return 90;
  return Math.min(Math.max(Math.floor(raw), 1), 3650);
}

/** The instant before which `EmailLog` rows are deleted, given `now`. */
export function emailLogCutoff(now: number = Date.now()): Date {
  return new Date(now - emailLogRetentionDays() * 24 * 60 * 60 * 1000);
}

/**
 * Opportunistic retention sweep — at most once an hour, never blocking a send,
 * never throwing. Same shape as the bucket sweep in lib/rate-limit.ts: no timer,
 * no cron row to forget to schedule, and it runs on the only event that can grow
 * the table.
 */
let lastPrune = 0;
const PRUNE_INTERVAL_MS = 60 * 60_000;
async function pruneEmailLog(now: number): Promise<void> {
  if (now - lastPrune < PRUNE_INTERVAL_MS) return;
  lastPrune = now;
  try {
    await (await prisma()).emailLog.deleteMany({
      where: { createdAt: { lt: emailLogCutoff(now) } },
    });
  } catch (e) {
    console.error("[email-render] EmailLog retention sweep failed:", e);
  }
}

/**
 * Append an `EmailLog` row for every send attempt. Never throws (logging must
 * not break a mail flow).
 *
 * The body is REDACTED before it is written — see `redactEmailSecrets`. Nothing
 * downstream re-reads a token out of this row, so redaction is lossless for
 * every purpose the log actually serves.
 */
export async function recordEmail(
  toEmail: string,
  subject: string,
  template: string | null,
  html: string,
  status: "SENT" | "FAILED",
  error?: string | null,
  userId?: string | null,
): Promise<void> {
  try {
    await (await prisma()).emailLog.create({
      data: {
        toEmail,
        subject: subject.slice(0, 500),
        template: template ?? null,
        html: redactEmailSecrets(html),
        status,
        error: error ? String(error).slice(0, 1000) : null,
        userId: userId ?? null,
      },
    });
  } catch (e) {
    console.error("[email-render] failed to record EmailLog:", e);
  }
  await pruneEmailLog(Date.now());
}

/// Email log: every message sent, with rendered HTML for admin preview
/// (/admin/logs?tab=email, `platform` area = ADMIN only per lib/rbac.ts).
///
/// `html` is the REDACTED body, not the body that was sent. `recordEmail` in
/// lib/email-render.ts strips secret-bearing query parameters (`?token=…`,
/// `?code=…`, …) before this row is written, so a leak of this table — or of a
/// database backup containing it — hands out no working password-reset or
/// email-verification links. That is what makes the guarantee stated on
/// EmailVerificationToken above TRUE: hashing the token is pointless if the
/// plaintext is copied into the audit log a moment later.
///
/// Rows are pruned to NXEON_EMAIL_LOG_RETENTION_DAYS (default 90) by an
/// opportunistic sweep in `recordEmail`; nothing here is kept forever.
model EmailLog {
  id        String   @id @default(cuid())
  toEmail   String
  subject   String
  template  String?  // template key (welcome, receipt, ...)
  html      String   // rendered HTML, secrets redacted — see the model comment
  status    String   @default("SENT") // SENT | FAILED
  error     String?
  userId    String?
  createdAt DateTime @default(now())

  @@index([createdAt])
}

