  const quoted = cmds.map((c) => `'${shq(c)}'`).join(" ");
  // EVERY interpolation is inside single quotes. `shq` escapes a value for use
  // INSIDE a single-quoted string — it is not a quoter, and a bare `${shq(x)}`
  // is simply an unquoted, word-splitting, metacharacter-honouring shell
  // argument. `-P` was written that way, so `rcon.port=1; curl … | sh` in the
  // customer's own server.properties ran as root on the hypervisor's SSH client
  // target with no further steps required.
  //
  // The `|| true` that used to end this line is gone. It forced exit 0, so the
  // `res.code === 0` test below was a constant and this function reported
  // "Pushed live settings via RCON." whether mcrcon worked, refused the
  // password, or was never reached. `execRemote` resolves with the real exit
  // code rather than rejecting, so nothing here can throw on a non-zero status —
  // the note just becomes true.
  const res = await execRemote(
    conn,
    `mcrcon -H 127.0.0.1 -P '${shq(port)}' -p '${shq(password)}' ${quoted} 2>&1`
  );
  notes.push(res.code === 0 ? "Pushed live settings via RCON." : "RCON push attempted (some settings may need a restart).");
}

/**
 * The RCON port to talk to, from an untrusted `rcon.port` value.
 *
 * Accepts only a bare 1–65535 decimal; anything else (empty, non-numeric, out of
 * range, or carrying a shell payload) falls back to Minecraft's default 25575.
 * Returns a string because it is interpolated into a command line, and returning
 * the parsed digits — never the caller's original text — is what makes the value
 * safe by construction rather than by escaping.
 */
function rconPort(raw: string | undefined): string {
  const n = Number(String(raw ?? "").trim());
  if (!Number.isInteger(n) || n < 1 || n > 65535) return "25575";
  return String(n);
}

