/**
 * What a VM's Proxmox config must be put back to after a backup restore.
 *
 * ── THE INCIDENT ─────────────────────────────────────────────────────────────
 *
 * `worker/restore.ts` restores a customer's vzdump archive over their live VMID
 * with `qmrestore --force`. That does not restore *disks into* an existing VM —
 * it replaces the VM, config and all. Whatever `net0`, `ipconfig0`, `cores` and
 * `memory` the archive recorded become the VM's identity again, silently, and
 * the handler then started it.
 *
 * Two independent consequences, both invisible to the customer and to us:
 *
 * 1. NETWORK IDENTITY — the serious one. Addresses are not permanent. Suspending
 *    a server releases its dedicated IP back to the pool (`releaseDedicatedIp`)
 *    and `lib/ipam.ts` hands released NAT addresses back out to new servers. So
 *    an archive taken before a suspend, a plan move or an IP change carries an
 *    address that may now belong to a DIFFERENT CUSTOMER. Restoring it booted a
 *    second guest onto that address on the shared bridge: two machines, one IP,
 *    on a segment they do not share a tenant with. Whose traffic arrives where is
 *    decided by ARP.
 *
 * 2. SIZE vs. BILLING — `cores`/`memory` came back at whatever plan the archive
 *    was taken under. A customer who upgraded after that backup was restored to
 *    the smaller plan while the `Server` row, the invoice and the renewal price
 *    all still said the larger one. Nothing reconciled the two.
 *
 * ── THE RULE ─────────────────────────────────────────────────────────────────
 *
 * The `Server` row is the authority on identity, never the archive. After a
 * restore the platform-owned keys are written back from that row and then READ
 * BACK and verified; if they did not take, the VM must not be started. A restore
 * that leaves a machine stopped is an inconvenience — one that boots on someone
 * else's address is an incident.
 *
 * This module is pure on purpose: no Prisma, no Proxmox, no clock, no env. It is
 * driven directly by test/restore-identity.test.ts, which is the only way the
 * "two customers, one IP" case can be exercised without a real restore.
 */

/** The sizing fields the platform owns, from `Server.plan`. */
export type RestorePlan = { cpuCores: number; ramMB: number };

/** A dedicated (public, OVH failover) address currently held by this server. */
export type RestoreDedicatedIp = {
  address: string;
  virtualMac: string | null;
  /** OVH failover gateway — `ovhGateway()` in lib/dedicated-ip.ts. */
  gateway: string;
};

/**
 * Everything needed to rebuild a VM's identity, read from the `Server` row and
 * its node at restore time — never from the archive.
 */
export type RestoreIdentityInput = {
  plan: RestorePlan;
  /** `Server.ipAddress` — the NAT address, when the server is not on a dedicated IP. */
  natIp: string | null;
  /** `gatewayIp(node.subnetPrefix)`. */
  natGateway: string;
  /** `node.bridge`, e.g. `vmbr1`. */
  natBridge: string;
  /** The row from `DedicatedIp`, or null for a NAT server. */
  dedicated: RestoreDedicatedIp | null;
};

/** Proxmox `POST /nodes/{node}/qemu/{vmid}/config` body. */
export type VmIdentityConfig = {
  cores: number;
  memory: number;
  onboot: number;
  net0: string;
  ipconfig0: string;
};

/**
 * Raised when the `Server` row cannot describe a network the VM may legally boot
 * on. The caller must fail the restore job rather than start the VM: leaving the
 * archive's stale address in place is precisely the outcome being prevented.
 */
export class RestoreIdentityError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "RestoreIdentityError";
  }
}

/**
 * The config a restored VM must be given, derived from the `Server` row.
 *
 * Mirrors what PROVISION writes in worker/index.ts (and what unsuspend rewrites)
 * so a restored machine is configured identically to a freshly provisioned one.
 */
export function restoreIdentityConfig(input: RestoreIdentityInput): VmIdentityConfig {
  const cores = Math.trunc(Number(input.plan?.cpuCores));
  const memory = Math.trunc(Number(input.plan?.ramMB));
  if (!Number.isFinite(cores) || cores < 1 || !Number.isFinite(memory) || memory < 1) {
    throw new RestoreIdentityError(
      "the server's plan has no usable cpuCores/ramMB, so the restored VM's size cannot be reasserted",
    );
  }

  const base = { cores, memory, onboot: 1 };

  if (input.dedicated) {
    // Public bridge + OVH Virtual MAC; failover IP as a /32 with the host gateway.
    // Without the vMAC the address does not route, and inventing one would put an
    // unbound MAC on the PUBLIC bridge — refuse instead.
    const mac = (input.dedicated.virtualMac ?? "").trim();
    if (!mac) {
      throw new RestoreIdentityError(
        `dedicated IP ${input.dedicated.address} has no Virtual MAC bound, so the restored VM has no valid public network config`,
      );
    }
    if (!input.dedicated.gateway?.trim()) {
      throw new RestoreIdentityError(
        `dedicated IP ${input.dedicated.address} has no gateway, so the restored VM has no valid public network config`,
      );
    }
    return {
      ...base,
      net0: `virtio=${mac},bridge=vmbr0`,
      ipconfig0: `ip=${input.dedicated.address}/32,gw=${input.dedicated.gateway.trim()}`,
    };
  }

  const ip = (input.natIp ?? "").trim();
  if (!ip) {
    throw new RestoreIdentityError(
      "the server row holds no IP address, so there is no address the restored VM may boot on",
    );
  }
  const gw = (input.natGateway ?? "").trim();
  if (!gw) {
    throw new RestoreIdentityError("no NAT gateway is configured for this server's node");
  }
  const bridge = (input.natBridge ?? "").trim();
  if (!bridge) {
    throw new RestoreIdentityError("no bridge is configured for this server's node");
  }
  return {
    ...base,
    net0: `virtio,bridge=${bridge}`,
    ipconfig0: `ip=${ip}/24,gw=${gw}`,
  };
}

/** Split a Proxmox device string (`virtio=AA:…,bridge=vmbr0`) into its parts. */
function parts(value: unknown): string[] {
  return String(value ?? "")
    .split(",")
    .map((s) => s.trim().toLowerCase())
    .filter(Boolean);
}

/**
 * Which of the requested keys did NOT take, comparing the config we asked for
 * against the config Proxmox reports.
 *
 * `net0`/`ipconfig0` are compared component-wise: PVE normalises and may ADD
 * fields (`firewall=1`, a `link_down` flag, a `,type=` it filled in). Requiring
 * a byte-exact match would fail a correct apply, and a test that fails on
 * correct behaviour gets deleted. Requiring every component we ASKED FOR to be
 * present is the property that actually matters — in particular that `ip=` is
 * the address the `Server` row holds and not the archive's.
 *
 * Returns human-readable mismatch descriptions; empty means the apply is proven.
 */
export function restoreIdentityMismatches(
  desired: VmIdentityConfig,
  actual: Record<string, unknown> | null | undefined,
): string[] {
  const out: string[] = [];
  if (!actual || typeof actual !== "object") {
    return ["Proxmox returned no config for the restored VM, so nothing could be verified"];
  }

  for (const key of ["cores", "memory", "onboot"] as const) {
    const want = Number(desired[key]);
    const got = Number((actual as Record<string, unknown>)[key]);
    if (!Number.isFinite(got) || got !== want) {
      out.push(`${key}: expected ${want}, VM reports ${String((actual as Record<string, unknown>)[key] ?? "unset")}`);
    }
  }

  for (const key of ["net0", "ipconfig0"] as const) {
    const want = parts(desired[key]);
    const got = new Set(parts((actual as Record<string, unknown>)[key]));
    const missing = want.filter((p) => !got.has(p));
    if (missing.length > 0) {
      out.push(
        `${key}: expected ${missing.join(", ")}, VM reports "${String(
          (actual as Record<string, unknown>)[key] ?? "unset",
        )}"`,
      );
    }
  }

  return out;
}

