async function loadServer(serverId: string) {
  // `plan` and `dedicatedIp` are loaded because a restore must reassert the
  // server's identity afterwards — see reapplyIdentity below. Without them the
  // handler has no way to know what the VM is supposed to be.
  const server = await db.server.findUnique({
    where: { id: serverId },
    include: { node: true, plan: true, dedicatedIp: true },
  });
  if (!server) throw new Error(`Server ${serverId} not found`);
  return server;
}

/**
 * Resolve a Proxmox client for the server's node (mirrors worker/index.ts).
 * Returns the node ROW alongside it: the bridge and subnet prefix are node
 * properties, and a second node with a different subnet must not be handed the
 * primary's gateway.
 */
async function nodeFor(server: any) {
  const n =
    server.node ??
    (await db.node.findFirst({ where: { isPrimary: true } })) ??
    (await db.node.findFirst({ where: { enabled: true } }));
  if (!n) {
    return {
      conn: {
        get: pve.get,
        post: pve.post,
        put: pve.put,
        del: pve.del,
        node: envNode,
        waitForTask,
        nextVmid,
        vmStatus: (v: number) => pve.get(`/nodes/${envNode}/qemu/${v}/status/current`),
      } as any,
      row: null as any,
    };
  }
  return {
    conn: pveFor({ apiUrl: n.apiUrl, pveNode: n.pveNode, tokenId: n.tokenId, tokenSecret: n.tokenSecret }),
    row: n,
  };
}

/**
 * Put the VM's identity back after `qmrestore --force` replaced its config with
 * the archive's, then PROVE it took before anything is started.
 *
 * The order is load-bearing: this runs BETWEEN the restore and the start. A VM
 * that boots first and is corrected afterwards has already spoken on the wire
 * with the archive's address, which may now belong to another customer. Any
 * failure here throws, which fails the job and leaves the machine stopped —
 * the only safe outcome.
 */
async function reapplyIdentity(conn: any, nodeRow: any, server: any, vmid: number): Promise<void> {
  const desired = restoreIdentityConfig({
    plan: { cpuCores: server.plan?.cpuCores, ramMB: server.plan?.ramMB },
    natIp: server.ipAddress ?? null,
    natGateway: gatewayIp(nodeRow?.subnetPrefix),
    natBridge: nodeRow?.bridge ?? "vmbr1",
    dedicated: server.dedicatedIp
      ? {
          address: server.dedicatedIp.address,
          virtualMac: server.dedicatedIp.virtualMac ?? null,
          gateway: ovhGateway(),
        }
      : null,
  });

  await conn.post(`/nodes/${conn.node}/qemu/${vmid}/config`, desired);

  // Read it back. A 200 on the config POST means PVE accepted the request, not
  // that the VM now holds those values — a pending-change file, a partially
  // applied write or a concurrent edit all return 200 and leave the archive's
  // network in place. The whole point of this function is that the address is
  // right, so it is checked rather than assumed.
  const current = await conn.get(`/nodes/${conn.node}/qemu/${vmid}/config`);
  const mismatches = restoreIdentityMismatches(desired, current as Record<string, unknown>);
  if (mismatches.length > 0) {
    throw new Error(
      `Restore stopped before starting the server: its network and size could not be restored to this ` +
        `account's configuration (${mismatches.join("; ")}). The VM has been left powered off — starting it ` +
        `could have put it on an IP address that now belongs to another customer. Contact support.`,
    );
  }
}

