/**
 * Whether an authenticated token carries a given scope.
 *
 * A scope is `resource:action` (`servers:read`). A token satisfies a request if
 * it carries:
 *   - the exact requested scope, or
 *   - the global wildcard `*`, or
 *   - the resource wildcard `servers:*`, or
 *   - the generic `read` scope, which satisfies any `*:read` request.
 *
 * ── EMPTY SCOPES ARE READ-ONLY, NOT FULL ACCESS ──────────────────────────────
 *
 * A token with no scopes recorded predates scoping. It used to return true for
 * ANY request — `if (scopes.length === 0) return true` — which is not
 * "backward compatible", it is "unscoped means unlimited". It survived review
 * only because the public API happens to be read-only today: `GET /api/v1/servers`
 * is the single token-authenticated route in the codebase. The first mutating
 * endpoint to land would have silently granted every legacy token the right to
 * call it, and nobody adding that endpoint would have had any reason to look here.
 *
 * A customer who created a token before scopes existed consented to reading their
 * account, because reading is all the API could do. They did not consent to a
 * future `servers:delete`. So an empty scope list now means exactly that: reads,
 * and nothing else. Fail closed, and let the failure be a 403 on a new endpoint
 * rather than a deletion nobody authorised.
 */
export function tokenHasScope(auth: ApiAuthResult, scope: string): boolean {
  if (!auth.ok) return false;
  if (!scope || typeof scope !== "string") return false;
  const scopes = auth.scopes ?? [];
  const [resource, action] = scope.split(":");

  if (scopes.length === 0) {
    // Legacy, pre-scoping token: reads only. `servers:read` yes, anything that
    // changes state no.
    return action === "read";
  }
  if (scopes.includes("*") || scopes.includes(scope)) return true;
  if (resource && scopes.includes(`${resource}:*`)) return true;
  if (action === "read" && scopes.includes("read")) return true;
  return false;
}

/**
 * Authenticate AND authorize in one call — the form every `/api/v1` route should
 * use.
 *
 * `tokenHasScope` on its own is advisory: nothing makes a route call it, and a
 * route that forgets is authenticated-but-unauthorized, which looks completely
 * normal in review. That is the second half of the same footgun, and it cannot be
 * fixed by being careful. It is fixed by there being a single entry point that
 * cannot answer "who is this" without also being told "to do what", plus the
 * tripwire in test/api-http-surface.test.ts asserting that no route under
 * app/api/v1 authenticates a token without checking a scope.
 *
 * Returns the same discriminated union as `authenticateApiToken`, so a route
 * handles one error shape:
 *
 *     const auth = await authorizeApiRequest(req, "servers:read");
 *     if (!auth.ok) return NextResponse.json({ error: auth.error }, { status: auth.status });
 */
export async function authorizeApiRequest(
  req: Request,
  scope: string,
): Promise<ApiAuthResult> {
  const auth = await authenticateApiToken(req);
  if (!auth.ok) return auth;
  if (!tokenHasScope(auth, scope)) {
    return { ok: false, status: 403, error: `Token is missing the required scope: ${scope}` };
  }
  return auth;
}

