/** `unknown` is the shared bucket for callers we cannot place. */
export const UNKNOWN_IP = "unknown";

/**
 * Strip an optional `:port` / `[v6]:port` wrapper and an IPv4-mapped IPv6 prefix
 * so the same peer always produces the same bucket key. `::ffff:127.0.0.1` and
 * `127.0.0.1` are one machine; without this they are two budgets.
 */
function normaliseAddress(value: string): string {
  let v = value.trim();
  if (v.startsWith("[")) {
    const end = v.indexOf("]");
    if (end !== -1) v = v.slice(1, end);
  } else if (v.includes(":") && net.isIP(v) === 0) {
    // host:port for IPv4 (a bare IPv6 has many colons and parses as an IP).
    v = v.split(":")[0];
  }
  const mapped = /^::ffff:((?:\d{1,3}\.){3}\d{1,3})$/i.exec(v);
  return mapped ? mapped[1] : v;
}

/** Anything with a `.get()`: `await headers()`, `req.headers`, or a `Request`. */
type HeaderLike = { get(name: string): string | null };
export type ClientIpSource = HeaderLike | { headers: HeaderLike };

function headersOf(source: ClientIpSource): HeaderLike {
  return typeof (source as HeaderLike)?.get === "function"
    ? (source as HeaderLike)
    : (source as { headers: HeaderLike }).headers;
}

/**
 * The caller's address, for use as a rate-limit key. NEVER attacker-controlled.
 *
 * ── THIS IS THE ONLY DEFINITION ──────────────────────────────────────────────
 *
 * There were two. This one owned the trusted-hop knob; `trustedClientIp` in
 * app/api/_lib/client-ip.ts owned IP-format validation and `::ffff:`/port
 * normalisation. Each was correct about something the other got wrong, they were
 * written days apart from the same incident, and a reader had no way to know
 * which one their call site should use. A second definition of an existing thing
 * is this repo's most common defect class and it caused two production bugs in
