input.old_string:
import { NextResponse } from "next/server";
import { checkRateLimit } from "@/lib/rate-limit";

/**
 * Small shared helpers for the public /api/tools/* network endpoints:
 * client-IP extraction, per-IP rate limiting, and consistent JSON errors.
 */

/** First hop of x-forwarded-for is the real client (nginx appends downstream). */
export function clientIp(req: Request): string {
  const xff = req.headers.get("x-forwarded-for") ?? "";
  const first = xff.split(",")[0]?.trim();
  return first || req.headers.get("x-real-ip") || "unknown";
}

/** JSON error with a status code. */
export function jsonError(message: string, status = 400) {
  return NextResponse.json({ ok: false, error: message }, { status });
}

/**
 * Per-IP throttle for a named tool. Returns a 429 response when over the limit,
 * otherwise null (caller proceeds). Defaults: 20 requests / minute / IP / tool.
 */
export function toolRateLimit(
  req: Request,
  tool: string,
  opts: { max?: number; windowMs?: number } = {},
): NextResponse | null {
  const { max = 20, windowMs = 60_000 } = opts;
  const rl = checkRateLimit(`tool:${tool}:${clientIp(req)}`, { max, windowMs });
  if (!rl.ok) {
    return NextResponse.json(
      { ok: false, error: `Rate limit reached. Try again in ${rl.retryAfterSec}s.` },
      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } },
    );
  }
  return null;
}
